                               'thirty-first':31}
                    if day_str in days_map:
                        day = days_map[day_str]
                    elif mname in months:
                        day = int(day_str)
                    if mname in months:
                        meas_date = datetime(int(year), months[mname], day)

            if pid not in patients_creat or (meas_date and (pid not in patients_creat or meas_date > patients_creat[pid]['date'])):
                patients_creat[pid] = {'value': val, 'date': meas_date}
                print(f'{pid}: {val} on {meas_date.date() if meas_date else "N/A"}')

print(f'\nTotal patients with creatinine: {len(patients_creat)}')

# Check abnormal
abnormal = {k:v for k,v in patients_creat.items() if v['value'] >= 1.2}
print(f'\nAbnormal creatinine (>=1.2): {len(abnormal)} patients')
for pid, v in abnormal.items():
    print(f'{pid}: {v}')

